output:
[
  {
    "name": "re-lint/recommended",
    "files": [
      "**/*.{ts,tsx,mts,cts,js,jsx,mjs,cjs}"
    ],
    "languageOptions": {},
    "plugins": {
      "re-lint": {
        "meta": {
          "name": "@re-cinq/eslint-plugin-re-lint",
          "version": "1.3.0"
        },
        "rules": {
          "callee-below-caller": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Require a top-level function to be declared below the function that first calls it (callers above callees)"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "exportedFirst": {
                      "type": "boolean"
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "calleeAboveCaller": "'{{callee}}' is declared above its caller '{{caller}}'; move it below"
              }
            }
          },
          "declare-near-use": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Require a const/let declaration to sit within a few statements of its first use in the same block"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "maxDistance": {
                      "type": "integer",
                      "minimum": 0
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "declaredTooEarly": "'{{name}}' is declared {{distance}} statements before its first use (max {{maxDistance}}); move it down"
              }
            }
          },
          "default-export-matches-filename": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "a default export's name matches its filename, so the component can be found by grepping its name"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "reserved": {
                      "description": "Whether Next.js reserved route files (page, layout, ...) must be pure re-exports",
                      "enum": [
                        "error",
                        "off"
                      ]
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "nameMismatch": "{{file}} default-exports \"{{name}}\". Rename one of the two so grepping \"{{name}}\" finds this file.",
                "unnamedDefault": "{{file}} default-exports something unnamed — name it {{stem}} so the file can be found by its component's name.",
                "reservedInlineDefault": "{{file}} must re-export its component from a file named after it, not declare it inline — every route file shares this name, so the component is unfindable.",
                "reservedNotPureReexport": "{{file}} re-exports its default but also declares {{name}}. Keep only imports, the re-export, and route-segment config here."
              }
            }
          },
          "max-boolean-operators": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Limit the number of boolean logical operators in a single condition or assignment"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "max": {
                      "type": "integer",
                      "minimum": 1
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "tooManyOperators": "Condition has {{count}} boolean operators (max {{max}}) — extract a named predicate."
              }
            }
          },
          "max-comment-lines": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Limit how many lines a comment (or run of consecutive line comments) may span; 0 bans comments entirely"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "max": {
                      "type": "integer",
                      "minimum": 0
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "tooLong": "Comment spans {{count}} lines (max {{max}}) — state the one constraint the code cannot show, or move the essay to a spec/ADR.",
                "noComments": "No comments in test files — the test name and the code must carry the meaning."
              }
            }
          },
          "max-expects": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Enforce a maximum number of expect calls per it/test callback (default 1)"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "max": {
                      "type": "integer",
                      "minimum": 1
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "tooManyExpects": "Test has {{count}} expect calls (max {{max}}); assert one object with toEqual/toMatchObject or split the test"
              }
            }
          },
          "max-member-chain": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Enforce a maximum member-access chain depth (Law of Demeter); fluent all-call chains, this, and well-known globals are exempt"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "max": {
                      "type": "integer",
                      "minimum": 1
                    },
                    "allowRoots": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "chainTooDeep": "Member chain '{{chain}}' reaches {{depth}} hops deep (max {{max}}); ask the direct collaborator for what you need"
              }
            }
          },
          "no-catch-as-control-flow": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "disallow catch clauses that swallow the error and fabricate a return value (try/catch as control flow)"
              },
              "schema": [],
              "messages": {
                "catchAsControlFlow": "This catch swallows the error and fabricates a return value — try/catch as control flow. Wrap only the throwing call in a status-returning probe, or observe the error before mapping it."
              }
            }
          },
          "no-closing-brace-comments": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow a comment after a closing brace or paren on the same line; a block short enough to read needs no marker"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {},
                  "additionalProperties": false
                }
              ],
              "messages": {
                "closingBraceComment": "Closing-brace comment; a block short enough to read needs no marker"
              }
            }
          },
          "no-commented-out-code": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow comments whose text is code; delete commented-out code, version control remembers it"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {},
                  "additionalProperties": false
                }
              ],
              "messages": {
                "commentedOutCode": "Commented-out code; delete it, version control remembers"
              }
            }
          },
          "no-cross-layer-import": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "enforce the folder layering declared in layers.yaml — a folder imports only what its entry lists"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "layers": {
                      "type": "object"
                    },
                    "aliases": {
                      "type": "object"
                    },
                    "root": {
                      "type": "string"
                    },
                    "firstPartyScopes": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "notAllowed": "`{{folder}}` may not import `{{target}}`. Its layers.yaml entry allows: {{allowed}}.",
                "unlistedFolder": "`{{folder}}` has no entry in layers.yaml, so it may import nothing. Give it one, or move the code into a folder that has one."
              }
            }
          },
          "no-dead-md-links": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "markdown links to repo files must resolve"
              },
              "schema": [],
              "messages": {
                "dead": "`{{target}}` does not exist. A link that no longer lands is worse than no link: a rename sweep rewrites it faithfully and the reference reads as current."
              }
            }
          },
          "no-duplicate-code": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow code blocks that jscpd reports as duplicated elsewhere in the scanned roots"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "minTokens": {
                      "type": "integer",
                      "minimum": 1
                    },
                    "minLines": {
                      "type": "integer",
                      "minimum": 1
                    },
                    "mode": {
                      "enum": [
                        "mild",
                        "weak",
                        "strict"
                      ]
                    },
                    "ignore": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    },
                    "roots": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      },
                      "minItems": 1
                    },
                    "formats": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    },
                    "jscpdBin": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "duplicate": "{{lines}} lines ({{tokens}} tokens) duplicated with {{twin}}:{{twinStart}}-{{twinEnd}}",
                "unavailable": "jscpd could not run ({{error}}) — install it with `npm i -D jscpd` or point the `jscpdBin` option at its run-jscpd.js"
              }
            }
          },
          "no-flag-params": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow boolean flag parameters and boolean literal arguments; split the function into one per behaviour"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "allowNamed": {
                      "type": "boolean"
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "flagParam": "Parameter '{{name}}' is a boolean flag; split the function into two named functions",
                "flagArgument": "Boolean literal argument selects a behaviour; call a dedicated function instead"
              }
            }
          },
          "no-forbidden-imports": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "disallow importing configured module specifiers (and their subpaths) in the files the rule is scoped to"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "forbidden": {
                      "description": "Module specifiers that may not be imported; a subpath under a specifier counts as the same module",
                      "type": "array",
                      "items": {
                        "type": "object",
                        "properties": {
                          "specifier": {
                            "type": "string"
                          },
                          "message": {
                            "type": "string"
                          }
                        },
                        "required": [
                          "specifier"
                        ],
                        "additionalProperties": false
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "forbiddenImport": "'{{specifier}}' may not be imported here — reach it through the layer that owns it.",
                "forbiddenImportCustom": "{{message}}"
              }
            }
          },
          "no-forwarding-class": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "disallow classes that only forward 1:1 to their single injected port — pass the port itself"
              },
              "fixable": "code",
              "schema": [],
              "messages": {
                "forwardingClass": "Every method of this class only forwards 1:1 to the injected `{{dep}}` — pass the port itself instead of wrapping it.",
                "forwardingUsage": "`{{name}}` only forwards to its injected port — hand out the {{port}} directly."
              }
            }
          },
          "no-hybrid-class": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow classes that mix public mutable fields with methods (half data structure, half object)"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "ignoreDecorated": {
                      "type": "boolean"
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "hybridClass": "Class '{{name}}' exposes {{fields}} mutable field(s) and {{methods}} method(s); make it a plain data type or hide its fields"
              }
            }
          },
          "no-inline-styles": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "styling lives in a stylesheet, not in a JSX style prop, so a shared decision has one home"
              },
              "schema": [],
              "messages": {
                "inlineStyle": "Inline style on <{{element}}>. Move it to a colocated stylesheet — an inline object cannot be shared, so the same rule ends up copied."
              }
            }
          },
          "no-io-in-view": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "disallow reaching the outside world (data layer, server actions, network globals) in presentational components — fetch in the container and pass props down (DDAU)"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "viewSuffixes": {
                      "description": "Basename suffixes that mark a file as a presentational view (<name><Suffix>.tsx)",
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    },
                    "dataModules": {
                      "description": "Exact import specifiers of the data layer; when empty the rule reports nothing",
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "ioImportInView": "Presentational component '{{name}}' must not reach the outside world — it imports '{{source}}'. Fetch in the container and pass the result down as props (data down, actions up).",
                "networkCallInView": "Presentational component '{{name}}' must not reach the outside world — it calls '{{api}}'. Move the network call into a container and pass the result down as props (data down, actions up)."
              }
            }
          },
          "no-negative-names": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow negated names (isNotReady, notFound, disableX, hideX, preventX) on declarations; name the positive case and negate at the use site"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "allow": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      },
                      "uniqueItems": true
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "negativeName": "'{{name}}' is a negative name; name the positive case ({{suggestion}}) and negate at the use site"
              }
            }
          },
          "no-nested-if": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow an if statement nested inside another if statement in the same function (else-if chains excluded)"
              },
              "schema": [],
              "messages": {
                "nestedIf": "Nested if — flatten with a guard clause, combine the conditions into a named predicate, or extract a function."
              }
            }
          },
          "no-nested-loop": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow a loop nested inside another loop in the same function"
              },
              "schema": [],
              "messages": {
                "nestedLoop": "Nested loop — extract the inner traversal into a named function, use an array method, or precompute a lookup map."
              }
            }
          },
          "no-nondeterministic-tests": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "Disallow Math.random, Date.now, new Date(), performance.now and crypto.randomUUID in test files unless faked (useFakeTimers / setSystemTime / spyOn Math.random / mock crypto)"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {},
                  "additionalProperties": false
                }
              ],
              "messages": {
                "nondeterministic": "{{call}} makes this test non-repeatable; inject the value or use fake timers"
              }
            }
          },
          "no-prop-mutation": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "disallow mutating props in components — data flows down read-only, changes flow up via callback props (DDAU)"
              },
              "schema": [],
              "messages": {
                "propMutation": "Don't mutate props ('{{name}}') — data flows down read-only; send the change up via a callback prop (data down, actions up)."
              }
            }
          },
          "no-reexport-only-module": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "disallow modules whose entire top level is re-exports — forward from an index, not from a body-less module"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "allow": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "reexportOnly": "This module only re-exports; nothing is decided here. Point callers at the real modules, or give it a body that composes them."
              }
            }
          },
          "no-row-types-outside-models": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "declare a table's shape once, in the models directory, instead of restating its columns"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "modelsDir": {
                      "description": "Path segment of the directory where row types belong; files under it are exempt",
                      "type": "string"
                    },
                    "exemptNames": {
                      "description": "Type names the rule never reports",
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "rowTypeOutsideModels": "\"{{name}}\" restates a table's columns outside the models directory. Declare the table there once and derive this type from that declaration. If this is a projection rather than a row, keep it and name the columns it actually reads."
              }
            }
          },
          "no-sql-in-web-ui": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "disallow SQL in the UI tier — the UI reads and writes through an HTTP API contract, never through the database"
              },
              "schema": [],
              "messages": {
                "sqlInWebUi": "SQL does not belong in the UI. Move the query behind an API route and call it from a typed client."
              }
            }
          },
          "no-vague-names": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Disallow vague binding names (data, temp, obj, x, ...) on declarations the author controls"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "names": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "vagueName": "'{{name}}' says nothing about what it holds — name the content (e.g. rows, retryBudget, settingsPatch)."
              }
            }
          },
          "prefer-api-error": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "prefer enforceTrue(cond, apiError(status), message) over an if-return that answers h.response({ error }).code(4xx)"
              },
              "fixable": "code",
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "enforceModule": {
                      "type": "object",
                      "properties": {
                        "specifier": {
                          "type": "string"
                        },
                        "sourceDir": {
                          "type": "string"
                        }
                      },
                      "required": [
                        "specifier"
                      ],
                      "additionalProperties": false
                    },
                    "errorModules": {
                      "type": "array",
                      "items": {
                        "type": "object",
                        "properties": {
                          "root": {
                            "type": "string"
                          },
                          "path": {
                            "type": "string"
                          }
                        },
                        "required": [
                          "root",
                          "path"
                        ],
                        "additionalProperties": false
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "preferApiError": "Prefer enforceTrue(cond, apiError({{status}}), message) over an if-return refusal — it reads as a precondition and narrows the checked expression."
              }
            }
          },
          "prefer-early-return": {
            "meta": {
              "type": "suggestion",
              "fixable": "code",
              "docs": {
                "description": "Guard clauses over else branches and wrapped tails: de-nest an else after a terminating if, split a non-terminating if/else into two ifs, and flip an if that wraps the whole happy path."
              },
              "messages": {
                "unnecessaryElse": "The if branch {{how}}, so this else only nests — de-nest its statements to follow the if.",
                "splitIntoTwoIfs": "No else branches: split into two ifs — `if (x)` and `if (!x)` — or restructure so the first branch returns.",
                "flipToGuard": "The happy path is wrapped in this if while {{tail}} statement(s) dangle after it — flip to `if (!(…))` guarding the tail and let the happy path run flat."
              },
              "schema": []
            }
          },
          "prefer-enforce-true": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "prefer enforceTrue(cond, ErrorType, message) / enforceOk(result, ErrorType) over an `if (!cond) throw` guard"
              },
              "fixable": "code",
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "enforceModule": {
                      "type": "object",
                      "properties": {
                        "specifier": {
                          "type": "string"
                        },
                        "sourceDir": {
                          "type": "string"
                        }
                      },
                      "required": [
                        "specifier"
                      ],
                      "additionalProperties": false
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "preferEnforce": "Prefer enforceTrue(cond, ErrorType, message) over an if-throw guard — it reads as a precondition and narrows the checked expression.",
                "preferEnforceOk": "Prefer enforceOk(result, ErrorType) over an if-throw result guard — the `.error` read moves inside the helper where the narrowing is legal.",
                "legacySignature": "enforceTrue takes (condition, ErrorType, errorMessage) — wrap a multi-argument error in a `(message) => …` factory."
              }
            }
          },
          "prefer-polymorphism": {
            "meta": {
              "type": "suggestion",
              "docs": {
                "description": "Prefer polymorphism (or a lookup table) to a switch or if/else-if chain that dispatches on an object's tag property"
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "minCases": {
                      "type": "integer",
                      "minimum": 2
                    },
                    "discriminants": {
                      "type": "array",
                      "items": {
                        "type": "string"
                      }
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "preferPolymorphism": "{{count}}-way dispatch on '{{discriminant}}'; a lookup table or polymorphic method replaces it"
              }
            }
          },
          "require-colocated-tests": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "tests must be colocated with their source, not in __tests__/"
              },
              "schema": [],
              "messages": {
                "colocate": "Test files must be colocated next to their source, not in a __tests__/ directory."
              }
            }
          },
          "require-fetch-timeout": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "require a signal on every outbound fetch so it cannot hang forever"
              },
              "schema": [],
              "messages": {
                "noTimeout": "fetch has no signal and can hang forever — pass `signal: AbortSignal.timeout(ms)` (or a caller's signal). A request meant to stay open (SSE, log tail) disables this rule on the line with a reason."
              }
            }
          },
          "require-intro-paragraph": {
            "meta": {
              "type": "problem",
              "docs": {
                "description": "require every spec.md / ADR to open with a lead paragraph (after the title, before the first ## section) that is rendered as the document summary."
              },
              "schema": [
                {
                  "type": "object",
                  "properties": {
                    "roots": {
                      "type": "object",
                      "properties": {
                        "spec": {
                          "type": "array",
                          "items": {
                            "type": "string"
                          }
                        },
                        "adr": {
                          "type": "array",
                          "items": {
                            "type": "string"
                          }
                        }
                      },
                      "additionalProperties": false
                    }
                  },
                  "additionalProperties": false
                }
              ],
              "messages": {
                "missingIntro": "Add a 1–2 sentence introductory paragraph (at least 40 characters) after the title (specs: below the status table; ADRs: below the H1) and before the first `##` section — the first paragraph is rendered as the document summary."
              }
            }
          },
          "require-spec-link": {
            "meta": {
              "type": "problem",
              "docs": {
