import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('compiles a static inputSchema at register time, accepting format annotations while throwing the tool name on an invalid schema', () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'schedule_event',
        description: 'Schedule an event',
        inputSchema: {
          type: 'object',
          properties: {when: {type: 'string', format: 'date-time', 'x-ui': 'picker'}},
        },
      },
      async () => ({result: 'ok'})
    );

    expect(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Invalid schema',
          inputSchema: {type: 'not-a-type'},
        },
        async () => ({result: 'ok'})
      )
    ).toThrow(/bad_schema_tool/);
  });
});

