}

function isSyncSchemaObject(schema: Record<string, unknown>): schema is SchemaObject {
  if (!isOptionalString(schema.id) || !isOptionalString(schema.$id)) return false;
  if (!isOptionalString(schema.$schema)) return false;
  return schema.$async === undefined || schema.$async === false;
}

function isOptionalString(value: unknown): value is string | undefined {
  return value === undefined || typeof value === 'string';
}

